def data(p,mime):return 'data:'+mime+';base64,'+base64.b64encode(Path(p).read_bytes()).decode()
def img(name,cl='',alt=None):
    p=Path('C:/Users/user/Downloads/간트차트.png') if name=='gantt' else Path('C:/Users/user/Downloads')/name
    return f'<img class="{cl}" src="{data(p,"image/png")}" alt="{html.escape(alt or name)}" data-source="{name}" tabindex="0">'
def slide(title,body,cl=''):
    i=len(slides)+1
