js='''
const slides=[...document.querySelectorAll('.slide')];let current=0;const count=document.querySelector('#count');
function scale(){document.documentElement.style.setProperty('--scale',Math.min((innerWidth-26)/1440,(innerHeight-78)/810))}
function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===current));count.textContent=(current+1)+' / '+slides.length; if(!document.body.classList.contains('presenting'))slides[current].scrollIntoView({behavior:'smooth',block:'center'})}
function toggle(){document.body.classList.toggle('presenting');document.querySelector('#mode').textContent=document.body.classList.contains('presenting')?'전체 보기':'발표 모드';scale();show(current)}
document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#mode').onclick=toggle;document.querySelector('#print').onclick=()=>print();
document.querySelector('#full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen()};
const modal=document.querySelector('dialog');document.querySelector('#close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};
document.querySelectorAll('.slide img').forEach(im=>{function zoom(){modal.querySelector('img').src=im.src;modal.querySelector('img').alt=im.alt;modal.querySelector('p').textContent=im.dataset.source==='gantt'?'기존 발표자료의 프로젝트 일정':im.dataset.source;modal.showModal()}im.onclick=zoom;im.onkeydown=e=>{if(e.key==='Enter')zoom()}});
addEventListener('keydown',e=>{if(modal.open)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='p')toggle();if(e.key==='Escape'&&document.body.classList.contains('presenting'))toggle()});addEventListener('resize',scale);document.body.classList.add('presenting');scale();show(0);
'''
